/* Chart.js - Basic charting functionality */
class Chart {
  constructor(ctx, config) {
    this.ctx = typeof ctx === 'string' ? document.getElementById(ctx) : ctx;
    this.config = config;
    this.render();
  }
  
  render() {
    const canvas = this.ctx;
    const context = canvas.getContext('2d');
    
    // Simple chart rendering based on type
    switch(this.config.type) {
      case 'bar':
        this.renderBar(context);
        break;
      case 'line':
        this.renderLine(context);
        break;
      case 'pie':
        this.renderPie(context);
        break;
      case 'doughnut':
        this.renderDoughnut(context);
        break;
      default:
        this.renderBar(context);
    }
  }
  
  renderBar(ctx) {
    const data = this.config.data;
    const width = this.ctx.width;
    const height = this.ctx.height;
    const barWidth = width / (data.labels.length * 2);
    
    ctx.clearRect(0, 0, width, height);
    
    // Draw bars
    data.datasets.forEach((dataset, datasetIndex) => {
      const color = dataset.backgroundColor || '#007bff';
      ctx.fillStyle = color;
      
      dataset.data.forEach((value, index) => {
        const barHeight = (value / Math.max(...dataset.data)) * (height - 40);
        const x = (index * barWidth * 2) + barWidth/2;
        const y = height - barHeight - 20;
        
        ctx.fillRect(x, y, barWidth, barHeight);
      });
    });
    
    // Draw labels
    ctx.fillStyle = '#333';
    ctx.font = '12px Arial';
    data.labels.forEach((label, index) => {
      const x = (index * barWidth * 2) + barWidth;
      ctx.fillText(label, x - (label.length * 3), height - 5);
    });
  }
  
  renderLine(ctx) {
    const data = this.config.data;
    const width = this.ctx.width;
    const height = this.ctx.height;
    const stepX = width / (data.labels.length - 1);
    
    ctx.clearRect(0, 0, width, height);
    
    data.datasets.forEach((dataset) => {
      const color = dataset.borderColor || '#007bff';
      ctx.strokeStyle = color;
      ctx.lineWidth = 2;
      
      ctx.beginPath();
      dataset.data.forEach((value, index) => {
        const x = index * stepX;
        const y = height - ((value / Math.max(...dataset.data)) * (height - 40)) - 20;
        
        if (index === 0) {
          ctx.moveTo(x, y);
        } else {
          ctx.lineTo(x, y);
        }
      });
      ctx.stroke();
    });
  }
  
  renderPie(ctx) {
    const data = this.config.data;
    const centerX = this.ctx.width / 2;
    const centerY = this.ctx.height / 2;
    const radius = Math.min(centerX, centerY) - 20;
    
    ctx.clearRect(0, 0, this.ctx.width, this.ctx.height);
    
    const total = data.datasets[0].data.reduce((a, b) => a + b, 0);
    let currentAngle = 0;
    
    data.datasets[0].data.forEach((value, index) => {
      const sliceAngle = (value / total) * 2 * Math.PI;
      const color = data.datasets[0].backgroundColor[index] || '#007bff';
      
      ctx.fillStyle = color;
      ctx.beginPath();
      ctx.moveTo(centerX, centerY);
      ctx.arc(centerX, centerY, radius, currentAngle, currentAngle + sliceAngle);
      ctx.closePath();
      ctx.fill();
      
      currentAngle += sliceAngle;
    });
  }
  
  renderDoughnut(ctx) {
    const data = this.config.data;
    const centerX = this.ctx.width / 2;
    const centerY = this.ctx.height / 2;
    const outerRadius = Math.min(centerX, centerY) - 20;
    const innerRadius = outerRadius * 0.6;
    
    ctx.clearRect(0, 0, this.ctx.width, this.ctx.height);
    
    const total = data.datasets[0].data.reduce((a, b) => a + b, 0);
    let currentAngle = 0;
    
    data.datasets[0].data.forEach((value, index) => {
      const sliceAngle = (value / total) * 2 * Math.PI;
      const color = data.datasets[0].backgroundColor[index] || '#007bff';
      
      ctx.fillStyle = color;
      ctx.beginPath();
      ctx.arc(centerX, centerY, outerRadius, currentAngle, currentAngle + sliceAngle);
      ctx.arc(centerX, centerY, innerRadius, currentAngle + sliceAngle, currentAngle, true);
      ctx.closePath();
      ctx.fill();
      
      currentAngle += sliceAngle;
    });
  }
}

window.Chart = Chart;